    cotizacionEmpresarial: cotizacionEmpresarialOrdinaria
      .plus(meiEmpresarial)
      .plus(solidaridadEmpresarial),
    cotizacionTrabajador: cotizacionTrabajadorOrdinaria
      .plus(meiTrabajador)
      .plus(solidaridadTrabajador),
  }
}
